// ?bfmeCallDUL@@YG?AVRva0058C2B0RefPtr@@PBD@Z
// partial score=0.95 date=2026-09-29
// 0x0058C2B0, 170 bytes.  Ours builds 166; the whole tail from `or ebx,2` to
// `ret 8` is byte-identical to retail and funclet $L387 is byte-identical to
// retail's 0x00C37334.  `tools/probe.py --shape` reports 2 structural
// differences in the entire body (see targets/game/reverse/identity_evidence/
// 0058c2b0-eh-structure.md for the proof and the measured table).
// cl: /DNDEBUG /MD /EHsc
//
// ---------------------------------------------------------------------------
// PROVED SIGNATURE (this is why the function returns a CLASS, not void *)
// ---------------------------------------------------------------------------
// The first stack slot is the object's address, not a value:
//   +006a  mov esi, [X+4]      ; esi = the hidden RETURN pointer
//   +006e  mov [esi], eax      ; returnObject.m_ptr = p
//   +0072  inc dword [eax+4]   ; if (p) ++p->ref
//   +0099  mov eax, esi        ; small class return: eax = the object address
//   +00a7  ret 8               ; [sret][const char *]
// The unwind map proves it independently: FuncInfo 0x00E267B8 has a state-0
// funclet at 0x00C37334 whose cleanup is
//   mov eax,[ebp-0x18] ; and eax,2 ; je ret
//   and dword [ebp-0x18],-3
//   mov ecx,[ebp+4]                       <- destroys the object AT [X+4]
//   jmp 0x0018336 -> 0x00107550 ReferencePointerReleaseThunk::release
// whose first instruction is `mov ecx,[ecx]`, i.e. `this` is the returned
// object and it releases `this->m_ptr`.  Only MSVC's sret pointer and a
// by-value class parameter can put an object in the first stack slot, and the
// by-value spelling emits a normal-path destructor retail does not have.
//
// The destructor MUST be user-declared and must not be throw().  VC7.1 treats an
// implicit destructor as throw() and registers no unwind action for it at all,
// which is why every earlier attempt (implicit ~RefCountPtr, and every sret
// spelling with a bare `release()` member) produced only two funclets.
//
// Frame (proved from the unwind map; EBP = entry ESP X):
//   X-0x18  EH flags word: bit0 = string temp alive, bit1 = return object alive
//   X-0x14  BFMERetailAsciiString temporary
//   X-0x10  raw operator new result
//   X-0x0c  saved fs:[0] chain, X-0x08 handler, X-0x04 EH state variable
//   X+0x04  the sret pointer,  X+0x08 the "PingAttack" string
//
// Retail order: operator new(0x18) -> BFMERetailAsciiString(what) ->
// Owner((int)&temp) -> returnObject.m_ptr = p (store first, then AddRef) ->
// string temp destructor -> return the object address.  The string temporary
// therefore lives until the end of the whole full expression, which is why it
// is written as a temporary inside the new-expression and not as a local.
//
// RESIDUE (4 bytes, one instruction): retail materialises the Owner
// constructor's argument with `lea ecx,[X-0x14]` and pushes ECX, and only then
// writes the string-temp flag `mov ebx,1`.  Ours forwards the string
// constructor's `this` return in EAX (`push eax`) and emits `mov ebx,1` first.
// VC7.1 folds `&class-prvalue` to the constructor's return value in every
// spelling tried (direct address-of, C-style and functional casts, const
// reference and pointer parameters, a const-ref helper returning `&s`, a
// user `operator int()` returning `(int)this`, a user `operator&`, a comma
// expression).  Only a NAMED lvalue gets a fresh `lea`, and a named local
// would run its constructor before `operator new`, which is not retail's order.
// See the identity-evidence note; treat this as a codegen residue.

void *operator new(unsigned int n);

class BFMERetailAsciiString
{
public:
	BFMERetailAsciiString(const char *text);
	~BFMERetailAsciiString() { releaseBuffer(); }
private:
	void releaseBuffer();
	char *m_data;
};

class Rva0058BF70Base
{
public:
	Rva0058BF70Base() : m_value(0) {}
	virtual ~Rva0058BF70Base() {}
	virtual void slot1();
	int m_value;
};

class Rva0058BF70Owner : public Rva0058BF70Base
{
public:
	Rva0058BF70Owner(int value);
	virtual ~Rva0058BF70Owner();
private:
	char m_pad[16];
};

// The returned smart pointer: one pointer, so MSVC passes a hidden return
// pointer in the first stack slot.  The user-declared destructor is what makes
// VC7.1 register the state-0 unwind action above; it tail-calls release().
// m_value is the shared reference count at [object+4] (the matched
// Rva0058BF70Owner constructor stores 0 there and the release body at
// 0x00107550 decrements it and calls vtable slot 0 with 1 at zero).
class Rva0058C2B0RefPtr
{
public:
	Rva0058C2B0RefPtr(Rva0058BF70Base *p) { m_ptr = p; if (p) ++p->m_value; }
	void release();
	~Rva0058C2B0RefPtr() { release(); }
private:
	Rva0058BF70Base *m_ptr;
};

Rva0058C2B0RefPtr __stdcall bfmeCallDUL(const char *what)
{
	return Rva0058C2B0RefPtr(new Rva0058BF70Owner((int)&BFMERetailAsciiString(what)));
}
